        /// <summary>
        /// Food, Travel, Business ve Family desteleri bu sürüme kadar Flutter
        /// tarafından kuruluyordu ve <c>starter_food_TR</c> gibi anahtarlar
        /// taşıyor. Artık bu dördünün de şablonu backend'de, o yüzden
        /// anahtarları <c>category_food_tr</c> biçimine çevirip desteleri
        /// <c>CategoryDeckSynchronizer</c>'a devrediyoruz.
        ///
        /// <para>
        /// Çevirmezsek senkronizasyon bu desteleri kendisinin saymaz ve
        /// yanlarına aynı içerikte ikinci bir deste kurar — kitaplığı bir kez
        /// bu yüzden elle temizlemek gerekti. Yalnızca anahtar değişiyor:
        /// kartlar, başlık ve tekrar geçmişi olduğu gibi kalır, eksik kelimeler
        /// senkronizasyonun tamamlama adımında eklenir.
        /// </para>
        ///
        /// <para>
        /// İstemci bayrak kodu (<c>TR</c>, <c>GB</c>, <c>JP</c>) kullanıyordu,
        /// katalog ise ISO kodu (<c>tr</c>, <c>en</c>, <c>ja</c>) — eşleme
        /// Languages tablosundaki <c>FlagCode</c> ile aynı. Geri alışta yön
        /// ters çevrilir, böylece migration geri sarıldığında desteler yine
        /// istemcinin tanıdığı anahtarla kalır.
        /// </para>
        /// </summary>
        private static void RekeyStarterDecks(MigrationBuilder migrationBuilder, bool toCategory)
        {
            var languageMap = new[]
            {
                ("GB", "en"), ("TR", "tr"), ("ES", "es"), ("FR", "fr"), ("DE", "de"),
                ("IT", "it"), ("PT", "pt"), ("JP", "ja"), ("KR", "ko"), ("CN", "zh"),
            };

            foreach (var slug in new[] { "food", "travel", "business", "family" })
            {
                foreach (var (flag, iso) in languageMap)
                {
                    var clientKey = $"starter_{slug}_{flag}";
                    var catalogKey = $"category_{slug}_{iso}";
                    var (from, to) = toCategory ? (clientKey, catalogKey) : (catalogKey, clientKey);

                    migrationBuilder.Sql(
                        $"UPDATE Decks SET StarterKey = '{to}' WHERE StarterKey = '{from}';");
                }
            }
        }

        /// <summary>
        /// Devralınan desteye karşılık gelen kategoriyi, seçili değilse
        /// kullanıcıya ekler.
        ///
        /// <para>
        /// Bu dört deste eskiden herkese kuruluyordu; kategori seçimine
        /// bakılmıyordu. Devralmadan sonra ise senkronizasyonun denetimine
        /// giriyorlar ve kategorisi seçili olmayan bir deste "istenmeyen"
        /// sayılıp —dokunulmamışsa— siliniyor. Yani sırf anahtar değiştirdiğimiz
        /// için, kullanıcının aylardır duran Yiyecek destesi ilk senkronizasyonda
        /// sessizce yok olurdu. Test verisinde on iki destenin onu bu durumdaydı.
        /// </para>
        ///
        /// <para>
        /// Destenin varlığı, uygulamanın o içeriği o kullanıcıya verdiğinin
        /// kanıtı; kategoriyi eklemek durumu tutarlı hale getirir ve mevcut
        /// davranışı korur. Öğrenen kategoriyi istemiyorsa seçimden çıkarabilir
        /// — o zaman deste de normal kurala göre gider.
        /// </para>
        ///
        /// <para>
        /// Geri alışta bu kayıtlar silinmiyor: migration uygulandıktan sonra
        /// kullanıcı bu kategorilere göre başka seçimler yapmış olabilir ve
        /// hangisinin buradan geldiğini ayırt edemeyiz.
        /// </para>
        /// </summary>
        private static void GrantCategoriesForAdoptedDecks(MigrationBuilder migrationBuilder)
        {
            var slugToCategoryId = new[]
            {
                ("food", 1), ("travel", 2), ("business", 3), ("family", 12),
            };

            foreach (var (slug, categoryId) in slugToCategoryId)
            {
                // '_' LIKE içinde joker; slug ile dil kodu arasındaki alt
                // çizgiyi [_] ile birebir eşleştiriyoruz.
                migrationBuilder.Sql($@"
                    INSERT INTO UserCategories (UserId, CategoryId)
                    SELECT DISTINCT d.UserId, {categoryId}
                    FROM Decks d
                    WHERE d.StarterKey LIKE 'category_{slug}[_]%'
                      AND NOT EXISTS (
                          SELECT 1 FROM UserCategories uc
                          WHERE uc.UserId = d.UserId AND uc.CategoryId = {categoryId});");
            }
        }
    }
